namespace sv_011c5108e68349ac8d9732545f1f82d9.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@* Step progress bar showing all steps with current/completed/future states *@

<nav aria-label="Application progress">
    <ol class="step-indicator d-flex list-unstyled mb-4 p-0">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var state = GetStepState(stepIndex);
            <li class="step-item flex-fill text-center @state" role="listitem">
                @if (state == "completed")
                {
                    <button type="button" class="btn btn-link step-btn p-0 text-decoration-none w-100"
                            @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                        <span class="step-circle bg-success text-white">&#10003;</span>
                        <span class="step-label d-block small mt-1 text-success fw-semibold">@StepNames[stepIndex]</span>
                    </button>
                }
                else
                {
                    <div class="w-100">
                        <span class="step-circle @(state == "active" ? "bg-primary text-white" : "bg-secondary text-white opacity-50")">
                            @(stepIndex + 1)
                        </span>
                        <span class="step-label d-block small mt-1 @(state == "active" ? "text-primary fw-semibold" : "text-muted")">
                            @StepNames[stepIndex]
                        </span>
                    </div>
                }
                @if (stepIndex < StepNames.Count - 1)
                {
                    <div class="step-connector"></div>
                }
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public int HighestCompletedStep { get; set; }
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private string GetStepState(int step)
    {
        if (step == CurrentStep) return "active";
        if (step < HighestCompletedStep) return "completed";
        return "future";
    }
}

@* Single work history entry form *@

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="card-title mb-0">Position @(Index + 1)</h6>
            @if (CanRemove)
            {
                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">
                    Remove
                </button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Company Name <span class="text-danger">*</span></label>
                <input type="text" class="form-control" value="@Company"
                       @onchange="e => UpdateField(company: e.Value?.ToString())" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                <input type="text" class="form-control" value="@Title"
                       @onchange="e => UpdateField(title: e.Value?.ToString())" />
            </div>
            <div class="col-md-4">
                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                <input type="date" class="form-control" value="@StartDate?.ToString("yyyy-MM-dd")"
                       @onchange="e => UpdateField(startDate: DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null)" />
            </div>
            <div class="col-md-4">
                <label class="form-label">End Date</label>
                <input type="date" class="form-control" value="@EndDate?.ToString("yyyy-MM-dd")"
                       disabled="@IsCurrent"
                       @onchange="e => UpdateField(endDate: DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null)" />
            </div>
            <div class="col-md-4 d-flex align-items-end">
                <div class="form-check mb-2">
                    <input type="checkbox" class="form-check-input" id="current-@Index" checked="@IsCurrent"
                           @onchange="e => UpdateField(isCurrent: (bool)(e.Value ?? false))" />
                    <label class="form-check-label" for="current-@Index">Currently working here</label>
                </div>
            </div>
            <div class="col-12">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" value="@Description"
                          @onchange="e => UpdateField(description: e.Value?.ToString())"></textarea>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime? StartDate { get; set; }
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private void UpdateField(string? company = null, string? title = null,
        DateTime? startDate = null, DateTime? endDate = null,
        bool? isCurrent = null, string? description = null)
    {
        var data = new WorkEntryData(
            company ?? Company,
            title ?? Title,
            startDate ?? StartDate,
            isCurrent ?? IsCurrent ? null : (endDate ?? EndDate),
            isCurrent ?? IsCurrent,
            description ?? Description
        );
        OnChanged.InvokeAsync(data);
    }

    public record WorkEntryData(string Company, string Title, DateTime? StartDate, DateTime? EndDate, bool IsCurrent, string Description);
}

