arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_011c5108e68349ac8d9732545f1f82d9.Models
@using sv_011c5108e68349ac8d9732545f1f82d9.Components.Pages.Apply
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="text-center mb-4">Job Application</h2>

    <StepIndicator CurrentStep="currentStep"
                   HighestCompletedStep="highestCompletedStep"
                   OnStepClicked="GoToStep" />

    <div class="mt-4">
        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@personalFullName"
                                  Email="@personalEmail"
                                  Phone="@personalPhone"
                                  Address="@personalAddress"
                                  ApplicationService="ApplicationService"
                                  OnNext="HandlePersonalNext" />
                break;

            case 1:
                <WorkHistoryStep Entries="workEntries"
                                 OnNext="HandleWorkNext"
                                 OnBack="GoBack" />
                break;

            case 2:
                <ReferencesStep Entries="referenceEntries"
                                OnNext="HandleReferencesNext"
                                OnBack="GoBack" />
                break;

            case 3:
                <CoverLetterStep CoverLetter="@coverLetter"
                                 OnNext="HandleCoverLetterNext"
                                 OnBack="GoBack" />
                break;

            case 4:
                <ReviewStep Personal="@personalInfo!"
                            WorkEntries="workEntries"
                            References="referenceEntries"
                            CoverLetter="@coverLetter"
                            ApplicationService="ApplicationService"
                            OnEditSection="GoToStep"
                            OnBack="GoBack" />
                break;
        }
    </div>
</div>

@code {
    private int currentStep;
    private int highestCompletedStep;

    // Step 1 state
    private string personalFullName = "";
    private string personalEmail = "";
    private string personalPhone = "";
    private string personalAddress = "";
    private PersonalInfo? personalInfo;

    // Step 2 state
    private List<WorkHistoryStep.WorkEntryState> workEntries = new() { new() };

    // Step 3 state
    private List<ReferencesStep.ReferenceState> referenceEntries = new() { new(), new() };

    // Step 4 state
    private string coverLetter = "";

    private void GoToStep(int step)
    {
        if (step < highestCompletedStep)
            currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void AdvanceStep()
    {
        currentStep++;
        if (currentStep > highestCompletedStep)
            highestCompletedStep = currentStep;
    }

    private void HandlePersonalNext(PersonalInfo info)
    {
        personalInfo = info;
        personalFullName = info.FullName;
        personalEmail = info.Email;
        personalPhone = info.Phone;
        personalAddress = info.Address;
        AdvanceStep();
    }

    private void HandleWorkNext(List<WorkHistoryStep.WorkEntryState> entries)
    {
        workEntries = entries;
        AdvanceStep();
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceState> entries)
    {
        referenceEntries = entries;
        AdvanceStep();
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        AdvanceStep();
    }
}

.step-indicator {
    position: relative;
    counter-reset: step;
}

.step-item {
    position: relative;
    z-index: 1;
}

.step-circle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    font-weight: 600;
    font-size: 0.875rem;
}

.step-btn {
    border: none;
    background: none;
    cursor: pointer;
}

.step-btn:hover .step-label {
    text-decoration: underline;
}

.step-connector {
    position: absolute;
    top: 18px;
    left: 60%;
    right: -10%;
    height: 2px;
    background-color: #dee2e6;
    z-index: -1;
}

.step-item.completed .step-connector {
    background-color: #198754;
}

::deep .last-no-border:last-child {
    border-bottom: none !important;
    margin-bottom: 0 !important;
    padding-bottom: 0 !important;
}

